// Error Trigger memberi { execution, workflow, trigger } dari eksekusi yang gagal.
const err = $input.first().json;

const workflowName = err.workflow && err.workflow.name ? err.workflow.name : 'Unknown workflow';
const nodeName = (err.execution && err.execution.error && err.execution.error.node && err.execution.error.node.name)
  || (err.execution && err.execution.lastNodeExecuted)
  || 'Unknown node';
const waktu = new Date().toISOString();
const errorMessage = (err.execution && err.execution.error && err.execution.error.message) || 'unknown error';

// Business key: cari order_id (HM-...) atau merchant_id (M0xx) di pesan error atau payload node yang gagal.
const haystack = JSON.stringify(err.execution && err.execution.error ? err.execution.error : {});
const orderMatch = haystack.match(/HM-[A-Z0-9-]+/);
const merchantMatch = haystack.match(/\bM0\d{2}\b/);
const businessKey = (orderMatch && orderMatch[0]) || (merchantMatch && merchantMatch[0]) || 'N/A';

const pesan = `\u26a0\ufe0f *Alert H8Mart Ops*\nWorkflow: ${workflowName}\nNode: ${nodeName}\nWaktu: ${waktu}\nBusiness key: ${businessKey}\nError: ${errorMessage}`;

return [{ json: { pesan, workflowName, nodeName, waktu, businessKey, errorMessage } }];
